#include "shims.h"
#include <errno.h>

/*
 * killcmd/printfcmd/testcmd used to live here as empty bodies while
 * builtins.def still listed `kill`, `printf` and `test [` as builtins. That
 * was a lie: the commands appeared in the builtin table, ran an empty
 * function, and returned whatever happened to be in the return register --
 * `test 1 -lt 2` reported failure, so every `while`/`if` loop was dead.
 *
 * builtins.c/builtins.h are generated by ./mkbuiltins from builtins.def, which
 * has all three commented out, so they are correctly resolved from PATH as
 * external commands. The empty bodies are gone rather than left to rot.
 */
char *
strchrnul(const char * s, int ch)
{
	char * result = strchr(s, ch);
	if (!result)
		return (char *)&s[strlen(s)];
	return result;
}

int
eaccess(const char *p, int mode)
{
	return access(p, mode);
}

void *
reallocarray(void * p, size_t n, size_t size)
{
	return realloc(p, n * size);
}

int
qsort_s(void * base, size_t nmemb, size_t size, fn_t * compar, void * thunk)
{
	if (nmemb > RSIZE_MAX || size > RSIZE_MAX)
		return EINVAL;
	if (nmemb > 0 && compar == NULL)
		return EINVAL;
	//qsort_r(base, nmemb, size, compar, thunk);
	return 0;
}
